header{
    display: flex;
    justify-content: space-between;
    width: 100%;
    height: 100px;
    background: linear-gradient(to right,rgb(209, 227, 248),rgb(170, 221, 237));
    border-radius: 20px 0;
    border-bottom:5px solid lightblue ;
}
header img{
    width: 100px;
    height: 100%;
}
nav{
    border-bottom:5px solid lightblue ;
    text-align: center;
}
nav ul li{
    display: inline;
}
a{
    color: blue;
    margin: 50px;
    font-size: 17px;
    font-weight: bold;
}
a:active
{
    color: red;
}
a:visited
{
    color:rgb(13, 0, 255);
}
main{
    display: flex; 
    justify-content: space-between;

}
section{
    width: 50%;
}
iframe{
    width: 100%;
    height: 100%;
}
aside{
    width: 50%;
}
figcaption{
    color: red;
    text-align: center;
    font-style: italic;
    transition: transform 4s;
}
figcaption:hover{
    transform: scale(1.3);

}
footer{
    display: flex;
    justify-content: space-between;
    height: 100px;
    border-top:5px solid lightblue ;
    border-radius: 20px 0 ;
}
footer div{
    font-weight: bold;
    text-align: center;
    margin-top: 20px; 
}
h1{
    text-align: center;
    color: red;
}
label {
    display: inline-block;
    width: 280px;
    line-height: 2.5;
}
legend
{

    padding: 10px;
    width: 300px;
    text-align: center;
    font-weight: bold;
    font-size: 20px;
    color: rgb(223, 60, 87);

}
fieldset{
    height:400px ;
    padding:10px ;
    border-left: 5px solid lightblue ;
}
label
{
    font-weight: bolder;
    padding-left: 20px;

}
input
{
    border-radius: 5px 0;
}
input[type=radio]
{
    margin-inline: 5px;
    width: 20px;
}
#center{
    margin-top: 20px;
    text-align: center;  
}

